modes.detail:
// ============ 为什么堆不用指针 ============
//
// 普通二叉树有"歪"的可能，所以必须用指针一个个接。但堆是**完全二叉树**：
// 除了最后一层，每一层都是满的，最后一层还靠左排。
//
// 形状这么规整，就带来一个漂亮的结果：**层序编号一确定，父子关系就确定了**。
//
//          1                 下标:  1  2  3  4  5  6
//        /   \                     ┌──┬──┬──┬──┬──┬──┐
//       3     2                data│─ │ 1│ 3│ 2│ 6│ 7│ 5│
//      / \   /                     └──┴──┴──┴──┴──┴──┴──┘
//     6   7 5
//
//   下标 1 的孩子是 2 和 3   →  左孩子 2i、右孩子 2i+1
//   下标 2 的孩子是 4 和 5   →  父结点是 i/2
//
// 所以整棵树就是一段连续内存，连一个指针都不用。
//
// ============ 0 号位置为什么空着 ============
//
// 为了让 i/2、2i、2i+1 这三个式子成立，下标必须从 **1** 开始。
// 所以数组的第 0 个位置通常空着，或者放一个"哨兵"值
// （一个比所有元素都小的数），这样上浮时不用判断边界。
//
// ============ 堆能做什么、不能做什么 ============
//
//   能：O(1) 拿到最小值；O(log n) 插入、删除最小值
//   不能：查找任意值（要 O(n) 挨个找）
//
// 因为堆只保证"父 <= 子"，**兄弟之间、叔侄之间没有任何大小约定**。
// 这一点和 BST 完全不同 —— 别把两者搞混。

// 堆能容纳的最大元素数
#define MAXN 1000

// 哨兵：比所有可能出现的值都小
// 放在 0 号位置，上浮时写到它就会自然停下，省掉一次边界判断。
#define MINDATA (-1000000)

// 最小堆
typedef struct
{
// 存储元素的数组，0 号位置放哨兵
    int *data;
// 当前元素个数（不是容量）
    int size;
// 容量上限
    int capacity;
} MinHeap;

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;

