modes.detail:
// ============ 下沉在做什么 ============
//
// 假设 p 位置放了一个"不该在这儿"的较大元素，要把它沉到合适的位置：
//
//   ① 看两个**孩子**里谁更小
//   ② 如果自己 <= 那个更小的孩子，说明位置对了，停
//   ③ 否则把孩子搬上来、自己沉下去，继续比较
//
// 走一遍（最小堆 {1,3,2,6,7,5}，把 0 号哨兵换上去后下沉）：
//
//        1                 把 8 放到根上
//      /   \
//     3     2
//    / \   /
//   6   7 5
//
//        8                 孩子 3 和 2，2 更小 → 2 搬上来
//      /   \
//     3     2
//          ↑ 8 沉到这儿
//
//        2
//      /   \
//     3     8             8 的孩子是 5 → 5 更小 → 5 搬上来
//    / \   /
//   6   7 5
//
//        2
//      /   \
//     3     5             8 没有孩子了，停下来
//    / \   /
//   6   7 8
//
// ============ 一个容易写错的地方 ============
//
// `if (child != H->size && ...)` —— 这个判断是必须的。
//
// 当 parent 只有一个左孩子时（完全二叉树里很常见），child 就等于 size，
// 没有右孩子。这时如果去比 data[child+1]，读到的是**堆外面的内存**。
// 概率不高但一定会在某个规模上突然出错，很难查。
//
// 判断"有没有右孩子"用的是 `child != H->size`，
// 而不是 `child < H->size` 或者 `child + 1 <= H->size` ——
// 想清楚"size 是最后一个元素的下标"就不容易写错了。

// 把位置 p 上的元素向下沉到合适的位置
void PercDown(MinHeap *H, int p)
{
// 父结点下标（会一路往下走）
    int parent;
// 较小的孩子下标
    int child;
// 暂存要下沉的元素 —— 不急着写回去，等位置定了再写
    int x;

// 先把要下沉的元素取出来
    x = H->data[p];

// 沿着"较小的孩子"一路往下
// parent * 2 <= H->size 表示还有左孩子（完全二叉树里，有左孩子就够判断）
    for (parent = p; parent * 2 <= H->size; parent = child)
    {
// 先假设较小的孩子是左孩子
        child = parent * 2;

// 如果有右孩子、且右孩子更小，就换成右孩子
// child != H->size 这个判断千万不能省，否则会读到堆外面的内存。
// 因为 size 是"最后一个元素的下标"，child == size 表示左孩子就是最后一个，
// 根本没有右孩子。
        if (child != H->size && H->data[child] > H->data[child + 1])
        {
            child++;
        }

// 如果自己已经不大于那个较小的孩子，位置就对了
        if (x <= H->data[child])
        {
            break;
        }

// 否则把小一点的孩子搬上来，自己继续往下比
        H->data[parent] = H->data[child];
    }

// 循环结束时 parent 就是该待的位置
    H->data[parent] = x;
}

