int main(void)
{
    MinHeap *H = CreateHeap(20);
    int i;

    /* 手工摆一个"根不合规矩"的堆：根是 8，其余是合法的小堆 */
    H->data[1] = 8;
    H->data[2] = 3;
    H->data[3] = 2;
    H->data[4] = 6;
    H->data[5] = 7;
    H->data[6] = 5;
    H->size = 6;

    printf("下沉前: ");
    for (i = 1; i <= H->size; i++) printf("%d ", H->data[i]);
    printf("\n（根 8 比孩子大，不合规矩）\n");

    PercDown(H, 1);

    printf("下沉后: ");
    for (i = 1; i <= H->size; i++) printf("%d ", H->data[i]);
    printf("\n（8 一直沉到没有孩子为止）\n");
    printf("检查: %s\n", CheckHeap(H) ? "合法" : "不合法");

    FreeHeap(H);
    return 0;
}

modes.detail:
// ============ 上浮和下沉是镜面对称 ============
//
//   下沉：跟**孩子**比，比自己小的就搬上来
//   上浮：跟**父亲**比，比自己大的就压下去
//
// 上浮用在**插入**：新元素先放到数组末尾（保持完全二叉树的形状），
// 然后让它一路往上浮到合适的位置。
//
// 走一遍：往 {1,3,2,6,7,5} 里插入 0
//
//        1                先放到末尾
//      /   \
//     3     2
//    / \   / \
//   6   7 5   0
//
//        1                0 比父亲 2 小 → 2 压下来，0 上去
//      /   \
//     3     0
//    / \   / \
//   6   7 5   2
//
//        0                0 比父亲 1 小 → 1 压下来，0 成了根
//      /   \
//     3     1
//    / \   / \
//   6   7 5   2
//
// ============ 哨兵在这里发挥作用 ============
//
// 循环条件里有 `H->data[i/2] > x`。当 i 走到 1 时，i/2 = 0，
// 而 0 号位置是 MINDATA —— 一定不大于 x，循环自然停下。
//
// 所以不用写 `i > 1 &&` 这个边界判断。哨兵值就是这么省事的。

// 把位置 p 上的元素向上浮到合适的位置
void PercUp(MinHeap *H, int p)
{
// 当前位置
    int i;
// 暂存要上浮的元素
    int x;

// 取出元素
    x = H->data[p];

// 只要父亲比自己大，就让父亲下来，自己继续往上
// 边界靠 0 号哨兵兜住：i 到 1 时，data[0] = MINDATA 一定不满足条件。
    for (i = p; H->data[i / 2] > x; i /= 2)
    {
        H->data[i] = H->data[i / 2];
    }

// 落位
    H->data[i] = x;
}

modes.short:
// 把位置 p 上的元素向上浮到合适的位置
void PercUp(MinHeap *H, int p)
{
// 当前位置
    int i;
// 暂存要上浮的元素
    int x;

// 取出元素
    x = H->data[p];

// 只要父亲比自己大，就让父亲下来，自己继续往上
    for (i = p; H->data[i / 2] > x; i /= 2)
    {
        H->data[i] = H->data[i / 2];
    }

// 落位
    H->data[i] = x;
}

