/* ======== [已给出] 模块 01 typedef ======== */

#define MAXN 1000

#define MINDATA (-1000000)

typedef struct
{
    int *data;
    int size;
    int capacity;
} MinHeap;

#define OK 1
#define ERROR 0
typedef int Status;

/* ======== [已给出] 模块 02 CreateHeap ======== */

MinHeap *CreateHeap(int capacity)
{
    MinHeap *H = (MinHeap *)malloc(sizeof(MinHeap));
    H->data = (int *)malloc((capacity + 1) * sizeof(int));
    H->data[0] = MINDATA;
    H->size = 0;
    H->capacity = capacity;
    return H;
}

void FreeHeap(MinHeap *H)
{
    if (H == NULL)
    {
        return;
    }
    free(H->data);
    free(H);
}

/* ======== [已给出] 模块 03 PercDown ======== */

void PercDown(MinHeap *H, int p)
{
    int parent;
    int child;
    int x;

    x = H->data[p];

    for (parent = p; parent * 2 <= H->size; parent = child)
    {
        child = parent * 2;

        if (child != H->size && H->data[child] > H->data[child + 1])
        {
            child++;
        }

        if (x <= H->data[child])
        {
            break;
        }

        H->data[parent] = H->data[child];
    }

    H->data[parent] = x;
}

