// ============ 怎么自查堆对不对 ============
//
// 打印数组只能看到一堆数字，看不出堆序。两个办法：
//
//   ① 检查每个结点是否 <= 它的两个孩子（下面用 CheckHeap 做）
//   ② 看堆顶是不是最小值
//
// 注意**数组打印出来的顺序不代表任何大小关系** ——
// 堆只保证父子之间，兄弟之间是乱的。

// 主函数
int main(void)
{
// 建一个堆
    MinHeap *H = CreateHeap(20);
// 待建堆的数据
    static const int a[] = { 6, 3, 7, 1, 5, 2, 4 };
// 计数
    int i;

// 把数据填进数组（注意从下标 1 开始）
    for (i = 0; i < 7; i++)
    {
        H->data[++H->size] = a[i];
    }
    PrintHeap("原始数据:", H);
    printf("（这时候还不是堆 —— 父子之间没有大小约束）\n\n");

// 建堆
    BuildHeap(H);
    PrintHeap("建堆之后:", H);
    printf("堆顶 = %d（一定是最小值）\n", H->data[1]);
    printf("检查堆序: %s\n\n", CheckHeap(H) ? "合法" : "不合法");

// 插入
    Insert(H, 0);
    PrintHeap("插入 0 后:", H);
    printf("堆顶 = %d（0 一路浮到了顶上）\n", H->data[1]);
    printf("检查堆序: %s\n\n", CheckHeap(H) ? "合法" : "不合法");

// 连续删除最小值
    printf("连续删除最小值: ");
    for (i = 0; i < 4; i++)
    {
        printf("%d ", DeleteMin(H));
    }
    printf("\n");
    PrintHeap("删了 4 个之后:", H);
    printf("检查堆序: %s\n", CheckHeap(H) ? "合法" : "不合法");
    printf("（每次删完，剩下的仍然是一个合法的堆）\n\n");

// 逐个删空
    printf("继续删到空: ");
    while (H->size > 0)
    {
        printf("%d ", DeleteMin(H));
    }
    printf("\n（输出一定是从小到大 —— 这就是堆排序的雏形）\n");

// 释放
    FreeHeap(H);
// 正常结束
    return 0;
}

