 *  写完按 Ctrl + Enter 编译运行，点"对比"看与参考实现的差异。
 * ==================================================================== */

modes.detail:
#include <stdio.h>
#include <stdlib.h>

// ============ 为什么堆不用指针 ============
//
// 普通二叉树有"歪"的可能，所以必须用指针一个个接。但堆是**完全二叉树**：
// 除了最后一层，每一层都是满的，最后一层还靠左排。
//
// 形状这么规整，就带来一个漂亮的结果：**层序编号一确定，父子关系就确定了**。
//
//          1                 下标:  1  2  3  4  5  6
//        /   \                     ┌──┬──┬──┬──┬──┬──┐
//       3     2                data│─ │ 1│ 3│ 2│ 6│ 7│ 5│
//      / \   /                     └──┴──┴──┴──┴──┴──┴──┘
//     6   7 5
//
//   下标 1 的孩子是 2 和 3   →  左孩子 2i、右孩子 2i+1
//   下标 2 的孩子是 4 和 5   →  父结点是 i/2
//
// 所以整棵树就是一段连续内存，连一个指针都不用。
//
// ============ 0 号位置为什么空着 ============
//
// 为了让 i/2、2i、2i+1 这三个式子成立，下标必须从 **1** 开始。
// 所以数组的第 0 个位置通常空着，或者放一个"哨兵"值
// （一个比所有元素都小的数），这样上浮时不用判断边界。
//
// ============ 堆能做什么、不能做什么 ============
//
//   能：O(1) 拿到最小值；O(log n) 插入、删除最小值
//   不能：查找任意值（要 O(n) 挨个找）
//
// 因为堆只保证"父 <= 子"，**兄弟之间、叔侄之间没有任何大小约定**。
// 这一点和 BST 完全不同 —— 别把两者搞混。

// 堆能容纳的最大元素数
#define MAXN 1000

// 哨兵：比所有可能出现的值都小
// 放在 0 号位置，上浮时写到它就会自然停下，省掉一次边界判断。
#define MINDATA (-1000000)

// 最小堆
typedef struct
{
// 存储元素的数组，0 号位置放哨兵
    int *data;
// 当前元素个数（不是容量）
    int size;
// 容量上限
    int capacity;
} MinHeap;

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;

// ============ 哨兵的作用 ============
//
// 把 0 号位置设成一个"比所有元素都小"的值，上浮循环就能写成：
//
//     for (i = p; H->data[i/2] > x; i /= 2) ...
//
// 而不用额外判断 i > 1。因为写到 0 号位置时条件一定不成立，循环自然结束。
//
// 这是个很典型的小技巧：**用一个不可能被越过的值来省掉边界检查**。

// 建一个能装 capacity 个元素的最小堆
MinHeap *CreateHeap(int capacity)
{
// 分配堆结构本身
    MinHeap *H = (MinHeap *)malloc(sizeof(MinHeap));
// 分配数组：多开一格给哨兵
    H->data = (int *)malloc((capacity + 1) * sizeof(int));
// 0 号放哨兵
    H->data[0] = MINDATA;
// 当前没有元素
    H->size = 0;
// 记下容量
    H->capacity = capacity;
// 返回
    return H;
}

// 释放堆
void FreeHeap(MinHeap *H)
{
// 先放数组
    if (H == NULL)
    {
        return;
    }
// 再放结构
    free(H->data);
    free(H);
}

// ============ 下沉在做什么 ============
//
// 假设 p 位置放了一个"不该在这儿"的较大元素，要把它沉到合适的位置：
//
//   ① 看两个**孩子**里谁更小
//   ② 如果自己 <= 那个更小的孩子，说明位置对了，停
//   ③ 否则把孩子搬上来、自己沉下去，继续比较
//
// 走一遍（最小堆 {1,3,2,6,7,5}，把 0 号哨兵换上去后下沉）：
//
//        1                 把 8 放到根上
//      /   \
//     3     2
//    / \   /
//   6   7 5
//
//        8                 孩子 3 和 2，2 更小 → 2 搬上来
//      /   \
//     3     2
//          ↑ 8 沉到这儿
//
//        2
//      /   \
//     3     8             8 的孩子是 5 → 5 更小 → 5 搬上来
//    / \   /
//   6   7 5
//
//        2
//      /   \
//     3     5             8 没有孩子了，停下来
//    / \   /
//   6   7 8
//
// ============ 一个容易写错的地方 ============
//
// `if (child != H->size && ...)` —— 这个判断是必须的。
//
// 当 parent 只有一个左孩子时（完全二叉树里很常见），child 就等于 size，
// 没有右孩子。这时如果去比 data[child+1]，读到的是**堆外面的内存**。
// 概率不高但一定会在某个规模上突然出错，很难查。
//
// 判断"有没有右孩子"用的是 `child != H->size`，
// 而不是 `child < H->size` 或者 `child + 1 <= H->size` ——
// 想清楚"size 是最后一个元素的下标"就不容易写错了。

// 把位置 p 上的元素向下沉到合适的位置
void PercDown(MinHeap *H, int p)
{
// 父结点下标（会一路往下走）
    int parent;
// 较小的孩子下标
    int child;
// 暂存要下沉的元素 —— 不急着写回去，等位置定了再写
    int x;

// 先把要下沉的元素取出来
    x = H->data[p];

// 沿着"较小的孩子"一路往下
// parent * 2 <= H->size 表示还有左孩子（完全二叉树里，有左孩子就够判断）
    for (parent = p; parent * 2 <= H->size; parent = child)
    {
// 先假设较小的孩子是左孩子
        child = parent * 2;

// 如果有右孩子、且右孩子更小，就换成右孩子
// child != H->size 这个判断千万不能省，否则会读到堆外面的内存。
// 因为 size 是"最后一个元素的下标"，child == size 表示左孩子就是最后一个，
// 根本没有右孩子。
        if (child != H->size && H->data[child] > H->data[child + 1])
        {
            child++;
        }

// 如果自己已经不大于那个较小的孩子，位置就对了
        if (x <= H->data[child])
        {
            break;
        }

// 否则把小一点的孩子搬上来，自己继续往下比
        H->data[parent] = H->data[child];
    }

// 循环结束时 parent 就是该待的位置
    H->data[parent] = x;
}

// ============ 上浮和下沉是镜面对称 ============
//
//   下沉：跟**孩子**比，比自己小的就搬上来
//   上浮：跟**父亲**比，比自己大的就压下去
//
// 上浮用在**插入**：新元素先放到数组末尾（保持完全二叉树的形状），
// 然后让它一路往上浮到合适的位置。
//
// 走一遍：往 {1,3,2,6,7,5} 里插入 0
//
//        1                先放到末尾
//      /   \
//     3     2
//    / \   / \
//   6   7 5   0
//
//        1                0 比父亲 2 小 → 2 压下来，0 上去
//      /   \
//     3     0
//    / \   / \
//   6   7 5   2
//
//        0                0 比父亲 1 小 → 1 压下来，0 成了根
//      /   \
//     3     1
//    / \   / \
//   6   7 5   2
//
// ============ 哨兵在这里发挥作用 ============
//
// 循环条件里有 `H->data[i/2] > x`。当 i 走到 1 时，i/2 = 0，
// 而 0 号位置是 MINDATA —— 一定不大于 x，循环自然停下。
//
// 所以不用写 `i > 1 &&` 这个边界判断。哨兵值就是这么省事的。

// 把位置 p 上的元素向上浮到合适的位置
void PercUp(MinHeap *H, int p)
{
// 当前位置
    int i;
// 暂存要上浮的元素
    int x;

// 取出元素
    x = H->data[p];

// 只要父亲比自己大，就让父亲下来，自己继续往上
// 边界靠 0 号哨兵兜住：i 到 1 时，data[0] = MINDATA 一定不满足条件。
    for (i = p; H->data[i / 2] > x; i /= 2)
    {
        H->data[i] = H->data[i / 2];
    }

// 落位
    H->data[i] = x;
}

// ============ 建堆为什么从 n/2 开始 ============
//
// 完全二叉树里，**下标大于 n/2 的结点全都是叶子**。
//
//   n = 7 时，n/2 = 3：
//
//          1        ← 需要调整（有孩子）
//        /   \
//       2     3     ← 2、3 需要调整（有孩子）
//      / \   / \
//     4   5 6   7   ← 4~7 都是叶子，不用调整
//
// 叶子没有孩子，本来就是一个合法的堆，不用管。
// 所以只需要从最后一个"有孩子的结点"（也就是 n/2）开始，
// **往前**逐个下沉。
//
// ============ 为什么是 O(n) 而不是 O(n log n) ============
//
// 看起来像"n/2 次下沉、每次最多 log n 层"，那不就 O(n log n) 吗？
//
// 但**大部分结点都在底层，它们下沉的距离很短**：
//
//   倒数第一层（叶子）：不用调
//   倒数第二层：最多沉 1 层        ← 结点很多
//   倒数第三层：最多沉 2 层        ← 结点少一半
//   ...
//   根：最多沉 log n 层            ← 只有 1 个
//
// 把每层的"结点数 × 下沉层数"加起来，这个级数是收敛的，总和是 O(n)。
//
// 相比之下，**逐个插入**建堆是 O(n log n) —— 因为每个新元素都要浮到顶上。
// 所以"一次性给一堆数"的时候要用 BuildHeap，不要一个个 Insert。

// 把已有数据整理成一个合法的最小堆
// 调用前要把数据填进 H->data[1..size]，并把 size 设好
void BuildHeap(MinHeap *H)
{
// 从最后一个非叶结点开始
    int i;

// 逐个往前下沉
// 从 n/2 递减到 1。之所以往前而不是往后，是因为下沉要保证
// "子树已经是堆" —— 从后往前才能满足这个前提。
    for (i = H->size / 2; i > 0; i--)
    {
        PercDown(H, i);
    }
}

// ============ 插入两步 ============
//
// ① **放到数组末尾**：这样完全二叉树的形状一定还是合法的
// ② **上浮**：把它往上顶到合适位置，恢复堆序
//
// 为什么必须先放末尾？如果随便找个位置插，形状就破了，
// 父子下标关系也就不成立了 —— 那样"用数组存树"这个前提就没了。
//
// 所以堆的插入顺序是固定的：
//
//     形状优先（放末尾） → 再调顺序（上浮）
//
// 删除正好相反：**先调顺序（把末尾元素搬到根、再下沉），形状自然保持**。

// 插入元素 x
Status Insert(MinHeap *H, int x)
{
// 满了就拒绝
    if (H->size >= H->capacity)
    {
        return ERROR;
    }

// ① 放到末尾，个数加一
    H->data[++H->size] = x;

// ② 上浮到合适位置
    PercUp(H, H->size);

// 成功
    return OK;
}

// ============ 删除最小值 ============
//
// 最小值就在根上（1 号位置），拿走很容易。麻烦的是**补位**：
//
// ① 记下根的值（这是要返回的答案）
// ② **把最后一个元素搬到根上**，size 减一
// ③ 让这个元素下沉到合适位置
//
// 走一遍（最小堆 {1,3,2,6,7,5}，删最小值）：
//
//        1                  ① 记下 1
//      /   \
//     3     2
//    / \   /
//   6   7 5
//
//        5                  ② 把末尾的 5 搬到根上，size 从 6 变 5
//      /   \
//     3     2
//    / \
//   6   7
//
//        2                  ③ 5 的孩子是 3 和 2，2 更小 → 2 搬上来
//      /   \
//     3     5
//    / \
//   6   7
//
// ============ 为什么搬末尾元素 ============
//
// 因为搬走末尾元素之后，**剩下的还是一棵完全二叉树**，形状没破。
//
// 如果随便挑一个元素搬到根上，形状就乱了，数组存树的前提也就没了。
// 这个思路和插入刚好对称：一个"先保形状再调顺序"，一个"先调顺序自然保形状"。

// 删除并返回最小值；空堆返回 MINDATA
int DeleteMin(MinHeap *H)
{
// 答案
    int minItem;
// 最后一个元素
    int last;

// 空堆没法删
    if (H->size == 0)
    {
        return MINDATA;
    }

// ① 根就是最小值，先记下来
    minItem = H->data[1];

// ② 把最后一个元素搬到根上，并让 size 减一
// 注意是"搬到根上"，不是"丢掉" —— 末尾那格从此不属于堆了，
// 它的值正好用来填根的空缺。
    last = H->data[H->size--];
    H->data[1] = last;

// ③ 让它下沉到合适位置
// size 已经减过了，所以 PercDown 看到的是一棵少了末尾元素的树。
    PercDown(H, 1);

// 返回答案
    return minItem;
}

// ============ 怎么自查堆对不对 ============
//
// 光看数组打印是看不出堆序的 —— 那只是一串数字。
// 所以这里给两个工具：
//
//   PrintHeap   把元素按数组顺序打出来
//   CheckHeap   逐个检查每个结点是否 <= 它的孩子
//
// 第二个体检尤其重要。堆的 bug 往往不会崩，只是"顺序悄悄错了"，
// 例如下沉方向反了、更新漏了。用 CheckHeap 一跑就露馅。
//
// 还要注意：**数组打印顺序不代表任何大小关系**。
// 堆只保证父子之间有序，兄弟之间是乱的。

// 打印堆里的元素（数组顺序）
void PrintHeap(const char *tag, MinHeap *H)
{
    int i;

    printf("%s size=%d : ", tag, H->size);
    for (i = 1; i <= H->size; i++)
    {
        printf("%d ", H->data[i]);
    }
    printf("\n");
}

// 检查是不是合法的堆：每个结点都要 <= 它的孩子
int CheckHeap(MinHeap *H)
{
    int i;

    for (i = 1; i * 2 <= H->size; i++)
    {
// 左孩子必须不小于自己
        if (H->data[i] > H->data[i * 2])
        {
            printf("  下标 %d (%d) 大于它的左孩子 %d\n", i, H->data[i], H->data[i * 2]);
            return 0;
        }
// 如果有右孩子，也要检查
        if (i * 2 + 1 <= H->size && H->data[i] > H->data[i * 2 + 1])
        {
            printf("  下标 %d (%d) 大于它的右孩子 %d\n", i, H->data[i], H->data[i * 2 + 1]);
            return 0;
        }
    }
    return 1;
}

// ============ 怎么自查堆对不对 ============
//
// 打印数组只能看到一堆数字，看不出堆序。两个办法：
//
//   ① 检查每个结点是否 <= 它的两个孩子（下面用 CheckHeap 做）
//   ② 看堆顶是不是最小值
//
// 注意**数组打印出来的顺序不代表任何大小关系** ——
// 堆只保证父子之间，兄弟之间是乱的。

// 主函数
int main(void)
{
// 建一个堆
    MinHeap *H = CreateHeap(20);
// 待建堆的数据
    static const int a[] = { 6, 3, 7, 1, 5, 2, 4 };
// 计数
    int i;

// 把数据填进数组（注意从下标 1 开始）
    for (i = 0; i < 7; i++)
    {
        H->data[++H->size] = a[i];
    }
    PrintHeap("原始数据:", H);
    printf("（这时候还不是堆 —— 父子之间没有大小约束）\n\n");

// 建堆
    BuildHeap(H);
    PrintHeap("建堆之后:", H);
    printf("堆顶 = %d（一定是最小值）\n", H->data[1]);
    printf("检查堆序: %s\n\n", CheckHeap(H) ? "合法" : "不合法");

// 插入
    Insert(H, 0);
    PrintHeap("插入 0 后:", H);
    printf("堆顶 = %d（0 一路浮到了顶上）\n", H->data[1]);
    printf("检查堆序: %s\n\n", CheckHeap(H) ? "合法" : "不合法");

// 连续删除最小值
    printf("连续删除最小值: ");
    for (i = 0; i < 4; i++)
    {
        printf("%d ", DeleteMin(H));
    }
    printf("\n");
    PrintHeap("删了 4 个之后:", H);
    printf("检查堆序: %s\n", CheckHeap(H) ? "合法" : "不合法");
    printf("（每次删完，剩下的仍然是一个合法的堆）\n\n");

// 逐个删空
    printf("继续删到空: ");
    while (H->size > 0)
    {
        printf("%d ", DeleteMin(H));
    }
    printf("\n（输出一定是从小到大 —— 这就是堆排序的雏形）\n");

// 释放
    FreeHeap(H);
// 正常结束
    return 0;
}

modes.short:
#include <stdio.h>
#include <stdlib.h>


// 堆能容纳的最大元素数
#define MAXN 1000

// 哨兵：比所有可能出现的值都小
#define MINDATA (-1000000)

// 最小堆
typedef struct
{
// 存储元素的数组，0 号位置放哨兵
    int *data;
// 当前元素个数（不是容量）
    int size;
// 容量上限
    int capacity;
} MinHeap;

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;


// 建一个能装 capacity 个元素的最小堆
MinHeap *CreateHeap(int capacity)
{
// 分配堆结构本身
    MinHeap *H = (MinHeap *)malloc(sizeof(MinHeap));
// 分配数组：多开一格给哨兵
    H->data = (int *)malloc((capacity + 1) * sizeof(int));
// 0 号放哨兵
    H->data[0] = MINDATA;
// 当前没有元素
    H->size = 0;
// 记下容量
    H->capacity = capacity;
// 返回
    return H;
}

// 释放堆
void FreeHeap(MinHeap *H)
{
// 先放数组
    if (H == NULL)
    {
        return;
    }
// 再放结构
    free(H->data);
    free(H);
}


// 把位置 p 上的元素向下沉到合适的位置
void PercDown(MinHeap *H, int p)
{
// 父结点下标（会一路往下走）
    int parent;
// 较小的孩子下标
    int child;
// 暂存要下沉的元素 —— 不急着写回去，等位置定了再写
    int x;

// 先把要下沉的元素取出来
    x = H->data[p];

// 沿着"较小的孩子"一路往下
    for (parent = p; parent * 2 <= H->size; parent = child)
    {
// 先假设较小的孩子是左孩子
        child = parent * 2;

// 如果有右孩子、且右孩子更小，就换成右孩子
        if (child != H->size && H->data[child] > H->data[child + 1])
        {
            child++;
        }

// 如果自己已经不大于那个较小的孩子，位置就对了
        if (x <= H->data[child])
        {
            break;
        }

// 否则把小一点的孩子搬上来，自己继续往下比
        H->data[parent] = H->data[child];
    }

// 循环结束时 parent 就是该待的位置
    H->data[parent] = x;
}


// 把位置 p 上的元素向上浮到合适的位置
void PercUp(MinHeap *H, int p)
{
// 当前位置
    int i;
// 暂存要上浮的元素
    int x;

// 取出元素
    x = H->data[p];

// 只要父亲比自己大，就让父亲下来，自己继续往上
    for (i = p; H->data[i / 2] > x; i /= 2)
    {
        H->data[i] = H->data[i / 2];
    }

// 落位
    H->data[i] = x;
}


// 把已有数据整理成一个合法的最小堆
void BuildHeap(MinHeap *H)
{
// 从最后一个非叶结点开始
    int i;

// 逐个往前下沉
    for (i = H->size / 2; i > 0; i--)
    {
        PercDown(H, i);
    }
}


// 插入元素 x
Status Insert(MinHeap *H, int x)
{
// 满了就拒绝
    if (H->size >= H->capacity)
    {
        return ERROR;
    }

// ① 放到末尾，个数加一
    H->data[++H->size] = x;

// ② 上浮到合适位置
    PercUp(H, H->size);

// 成功
    return OK;
}


// 删除并返回最小值；空堆返回 MINDATA
int DeleteMin(MinHeap *H)
{
// 答案
    int minItem;
// 最后一个元素
    int last;

// 空堆没法删
    if (H->size == 0)
    {
        return MINDATA;
    }

// ① 根就是最小值，先记下来
    minItem = H->data[1];

// ② 把最后一个元素搬到根上，并让 size 减一
    last = H->data[H->size--];
    H->data[1] = last;

// ③ 让它下沉到合适位置
    PercDown(H, 1);

// 返回答案
    return minItem;
}


// 打印堆里的元素（数组顺序）
void PrintHeap(const char *tag, MinHeap *H)
{
    int i;

    printf("%s size=%d : ", tag, H->size);
    for (i = 1; i <= H->size; i++)
    {
        printf("%d ", H->data[i]);
    }
    printf("\n");
}

// 检查是不是合法的堆：每个结点都要 <= 它的孩子
int CheckHeap(MinHeap *H)
{
    int i;

    for (i = 1; i * 2 <= H->size; i++)
    {
// 左孩子必须不小于自己
        if (H->data[i] > H->data[i * 2])
        {
            printf("  下标 %d (%d) 大于它的左孩子 %d\n", i, H->data[i], H->data[i * 2]);
            return 0;
        }
// 如果有右孩子，也要检查
        if (i * 2 + 1 <= H->size && H->data[i] > H->data[i * 2 + 1])
        {
            printf("  下标 %d (%d) 大于它的右孩子 %d\n", i, H->data[i], H->data[i * 2 + 1]);
            return 0;
        }
    }
    return 1;
}


// 主函数
int main(void)
{
// 建一个堆
    MinHeap *H = CreateHeap(20);
// 待建堆的数据
    static const int a[] = { 6, 3, 7, 1, 5, 2, 4 };
// 计数
    int i;

// 把数据填进数组（注意从下标 1 开始）
    for (i = 0; i < 7; i++)
    {
        H->data[++H->size] = a[i];
    }
    PrintHeap("原始数据:", H);
    printf("（这时候还不是堆 —— 父子之间没有大小约束）\n\n");

// 建堆
    BuildHeap(H);
    PrintHeap("建堆之后:", H);
    printf("堆顶 = %d（一定是最小值）\n", H->data[1]);
    printf("检查堆序: %s\n\n", CheckHeap(H) ? "合法" : "不合法");

// 插入
    Insert(H, 0);
    PrintHeap("插入 0 后:", H);
    printf("堆顶 = %d（0 一路浮到了顶上）\n", H->data[1]);
    printf("检查堆序: %s\n\n", CheckHeap(H) ? "合法" : "不合法");

// 连续删除最小值
    printf("连续删除最小值: ");
    for (i = 0; i < 4; i++)
    {
        printf("%d ", DeleteMin(H));
    }
    printf("\n");
    PrintHeap("删了 4 个之后:", H);
    printf("检查堆序: %s\n", CheckHeap(H) ? "合法" : "不合法");
    printf("（每次删完，剩下的仍然是一个合法的堆）\n\n");

// 逐个删空
    printf("继续删到空: ");
    while (H->size > 0)
    {
        printf("%d ", DeleteMin(H));
    }
    printf("\n（输出一定是从小到大 —— 这就是堆排序的雏形）\n");

// 释放
    FreeHeap(H);
// 正常结束
    return 0;
}

